  it('lists exactly who is asleep for every hour of each compromise window', () => {
    const ids = [...DEFAULT_CITY_IDS, 'kathmandu', 'johannesburg', 'sao-paulo', 'auckland', 'tehran', 'tokyo', 'london', 'new-york', 'honolulu']
